use blit_core::remote::transfer::sink::SinkOutcome;
fn main() {
    let display = "dup\u{fffd}";
    let mut outcome = SinkOutcome::default();
    outcome.record_known_failure(display, None, "missing");
    outcome.record_failure(display, "write error");
    let (paths, raw, truncated) = outcome.wire_failed_identities();
    println!("before manifest resolution: failures={} wire paths={} raw={raw:?} truncated={truncated}", outcome.files_failed_total, paths.len());
    let resolved = outcome.named_raw(|_| Some(b"dup\xff".to_vec()));
    let (after, raw, truncated) = resolved.wire_failed_identities();
    println!("after manifest resolution: failures={} wire paths={} raw={raw:?} truncated={truncated}", resolved.files_failed_total, after.len());
}
