$filePath = Join-Path $probeTree 'crates/blit-core/src/copy/file_copy/mod.rs'
$originalBytes = [IO.File]::ReadAllBytes($filePath)
$originalText = [IO.File]::ReadAllText($filePath)
$mark = 'fn an_ordinary_path_is_walked_by_the_kernel() {'
if ($originalText.Split($mark,[StringSplitOptions]::None).Count -ne 2) {throw 'expected a single test'}
try {
    [IO.File]::WriteAllText($filePath, $originalText.Replace($mark, $mark + [Environment]::NewLine + '        super::NO_OPENAT2.with(|refused| refused.set(true));'))
    cargo test -p blit-core --lib copy::file_copy::mode_tests::an_ordinary_path_is_walked_by_the_kernel -- --exact *> kernel-denied.log
    Write-Output "kernel unavailable via existing test seam: exit=$LASTEXITCODE"
    Get-Content -Tail 18 kernel-denied.log
} finally {
    [IO.File]::WriteAllBytes($filePath, $originalBytes)
}
cargo test -p blit-core --lib copy::file_copy::mode_tests::an_ordinary_path_is_walked_by_the_kernel -- --exact *> kernel-restored.log
Write-Output "normal kernel test exit=$LASTEXITCODE"
Get-Content -Tail 6 kernel-restored.log

