$walkFile = Join-Path $probeTree 'crates/blit-core/src/copy/file_copy/resume.rs'
$walkSaved = [IO.File]::ReadAllBytes($walkFile)
$walkTest = @'

#[cfg(all(test, target_os = "linux"))]
mod independent_directory_identity_check {
    use super::*;
    use std::os::fd::AsRawFd as _;
    use std::os::unix::fs::MetadataExt as _;
    #[test]
    fn parent_identity_after_an_ordinary_rename() {
        let workspace = tempfile::tempdir().unwrap();
        let root = workspace.path();
        let before = root.join("parent");
        std::fs::create_dir_all(before.join("child")).unwrap();
        let expected = std::fs::metadata(&before).unwrap().ino();
        let held = crate::copy::Within::hold(root.to_path_buf());
        let fd = held.held.as_ref().unwrap().as_raw_fd();
        let mut walk = Walk::new(&held, fd, root);
        walk.enter(Walk::names(Path::new("parent/child")), false).unwrap();
        std::fs::rename(&before, root.join("parent-renamed")).unwrap();
        std::fs::create_dir(&before).unwrap();
        let replacement = std::fs::metadata(&before).unwrap().ino();
        if walk.up().is_ok() {
            let returned = std::fs::File::from(walk.into_directory().unwrap()).metadata().unwrap().ino();
            println!("original {expected}, replacement {replacement}, returned {returned}");
            assert_eq!(returned, expected);
        }
    }
}
'@
try {
    [IO.File]::AppendAllText($walkFile, [Environment]::NewLine + $walkTest)
    cargo test -p blit-core --lib independent_directory_identity_check -- --nocapture *> parent-identity.log
    Write-Output "parent identity exit=$LASTEXITCODE"
    Get-Content -Tail 21 parent-identity.log
} finally {
    [IO.File]::WriteAllBytes($walkFile, $walkSaved)
}

